    },
    {
      "id": "P2",
      "text": "Date of service: November 5, 2026"
    },
    {
      "id": "P3",
      "text": "Endoscopist: Samuel Achterberg, MD (fictional)"
    },
    {
      "id": "P4",
      "text": "Procedure: The colonoscope was advanced to the cecum; the appendiceal orifice was identified."
    },
    {
      "id": "P5",
      "text": "- Sigmoid colon at 30 cm: two separate lesions lie side by side, about 1 cm apart."
    },
    {
      "id": "P6",
      "text": "- Lesion A: an 8 mm sessile polyp, removed completely with a cold snare and retrieved."
    },
    {
      "id": "P7",
      "text": "- Lesion B: a 20 mm firm, ulcerated mass with irregular margins, suspicious for malignancy."
    },
    {
      "id": "P8",
      "text": "- Lesion B was biopsied with cold forceps (six samples) and was left in place, not removed."
    },
    {
      "id": "P9",
      "text": "1. Lesion A: 8 mm sigmoid polyp, removed by cold snare."
    },
    {
      "id": "P10",
      "text": "2. Lesion B: 20 mm sigmoid mass suspicious for malignancy, biopsied and left in place."
    }
